-- Best-effort household-to-building links for Trung Chanh 2 (tc2-drawing-20261108-estimated).
-- Lower confidence than tc2-drawing-20261108: officers are expected to correct these on the 3D map.
-- Generated data: stable household codes, building IDs and public footprint geometry only.
-- Safe on any environment: unknown households are skipped; a household that already has a link keeps it.
ALTER TABLE public.gis_field_building_household_import ALTER COLUMN match_tier TYPE varchar(32);
ALTER TABLE public.gis_field_building_household_import DROP CONSTRAINT gis_field_building_household_import_match_tier_check;
ALTER TABLE public.gis_field_building_household_import ADD CONSTRAINT gis_field_building_household_import_match_tier_check
    CHECK (match_tier IN ('exact','hamlet','base','multi_label','other_hamlet','sibling','ambiguous_footprint','far_footprint','crowded'));

CREATE TEMP TABLE stage_tc2_building2 (building_id varchar(120) PRIMARY KEY, feature_json text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE stage_tc2_link2 (household_code varchar(255) PRIMARY KEY, building_id varchar(120) NOT NULL, match_tier varchar(32) NOT NULL) ON COMMIT DROP;

CREATE TEMP TABLE resolved_tc2_link2 ON COMMIT DROP AS
SELECT l.household_code, h.id AS household_id, l.building_id, l.match_tier,
       NOT EXISTS (SELECT 1 FROM public.gis_field_building b WHERE b.id = l.building_id) AS building_created
FROM stage_tc2_link2 l
JOIN public.household h ON h.code = l.household_code
WHERE NOT EXISTS (SELECT 1 FROM public.gis_field_building_household x WHERE x.household_id = h.id);

SELECT DISTINCT s.building_id, s.feature_json
FROM stage_tc2_building2 s JOIN resolved_tc2_link2 r ON r.building_id = s.building_id AND r.building_created;

UPDATE public.gis_field_building b
SET feature_json = jsonb_set(b.feature_json::jsonb, '{properties,householdIds}',
    coalesce(b.feature_json::jsonb #> '{properties,householdIds}', '[]'::jsonb) || a.ids, true)::text
FROM (SELECT building_id, jsonb_agg(household_id::text ORDER BY household_id) AS ids FROM resolved_tc2_link2 GROUP BY building_id) a
WHERE b.id = a.building_id;

SELECT 'tc2-drawing-20261108-estimated', r.household_code, r.household_id, r.building_id, r.match_tier, r.building_created,
       CASE WHEN r.building_created THEN md5((b.feature_json::jsonb #- '{properties,householdIds}')::text) END
FROM resolved_tc2_link2 r JOIN public.gis_field_building b ON b.id = r.building_id;
